from z3 import *

def solve_graceful():
    V = [Int(f'v_{i}') for i in range(24)]
    edges = []
    for g in range(8):
        edges.append((g*3 + 0, g*3 + 1))
        edges.append((g*3 + 1, g*3 + 2))
        edges.append((g*3 + 0, g*3 + 2))
    for g in range(7):
        for i in range(3):
            edges.append((g*3 + i, (g+1)*3 + i))

    s = Solver()
    for v in V:
        s.add(v >= 0, v <= 45)
    s.add(Distinct(V))

    edge_labels = []
    for i, (u, v) in enumerate(edges):
        diff = Int(f'e_{i}')
        s.add(Or(diff == V[u] - V[v], diff == V[v] - V[u]))
        edge_labels.append(diff)

    for e in edge_labels:
        s.add(e >= 1, e <= 45)
    s.add(Distinct(edge_labels))

    s.set("timeout", 55000)
    res = s.check()
    if res == sat:
        print("SAT")
    elif res == unsat:
        print("UNSAT")
    else:
        print("UNKNOWN")

solve_graceful()

from z3 import *

def check_parity():
    X = [Int(f'x_{i}') for i in range(24)]
    edges = []
    for g in range(8):
        edges.append((g*3 + 0, g*3 + 1))
        edges.append((g*3 + 1, g*3 + 2))
        edges.append((g*3 + 0, g*3 + 2))
    for g in range(7):
        for i in range(3):
            edges.append((g*3 + i, (g+1)*3 + i))

    s = Solver()
    for x in X:
        s.add(Or(x == 0, x == 1))

    odd_edges = []
    for u, v in edges:
        is_odd = Int(f'odd_{u}_{v}')
        s.add(is_odd == If(X[u] != X[v], 1, 0))
        odd_edges.append(is_odd)

    s.add(Sum(odd_edges) == 23)

    if s.check() == sat:
        print("Parity SAT")
    else:
        print("Parity UNSAT")

check_parity()

from pysat.solvers import Glucose4
import itertools

def solve():
    # V = 24, E = 45
    # Variables:
    # x[v][l] = 1 if vertex v has label l, for v in 0..23, l in 0..45
    # e[u][v][d] = 1 if edge (u,v) has difference d, for d in 1..45

    edges = []
    for g in range(8):
        edges.append((g*3 + 0, g*3 + 1))
        edges.append((g*3 + 1, g*3 + 2))
        edges.append((g*3 + 0, g*3 + 2))
    for g in range(7):
        for i in range(3):
            edges.append((g*3 + i, (g+1)*3 + i))

    solver = Glucose4()

    def var_x(v, l):
        return 1 + v * 46 + l

    def var_e(i, d):
        return 1 + 24 * 46 + i * 45 + (d - 1)

    # Each vertex has exactly one label
    for v in range(24):
        solver.add_clause([var_x(v, l) for l in range(46)])
        for l1 in range(46):
            for l2 in range(l1 + 1, 46):
                solver.add_clause([-var_x(v, l1), -var_x(v, l2)])

    # Each label is used at most once
    for l in range(46):
        for v1 in range(24):
            for v2 in range(v1 + 1, 24):
                solver.add_clause([-var_x(v1, l), -var_x(v2, l)])

    # Each edge has exactly one difference
    for i in range(45):
        solver.add_clause([var_e(i, d) for d in range(1, 46)])
        for d1 in range(1, 46):
            for d2 in range(d1 + 1, 46):
                solver.add_clause([-var_e(i, d1), -var_e(i, d2)])

    # Each difference is used exactly once
    for d in range(1, 46):
        solver.add_clause([var_e(i, d) for i in range(45)])
        for i1 in range(45):
            for i2 in range(i1 + 1, 45):
                solver.add_clause([-var_e(i1, d), -var_e(i2, d)])

    # Link vertices and edges
    for i, (u, v) in enumerate(edges):
        for d in range(1, 46):
            # If e[i][d] is true, then for some l, x[u][l] and x[v][l+d] or x[v][l] and x[u][l+d]
            # e[i][d] => OR_l (x[u][l] AND x[v][l+d]) OR (x[v][l] AND x[u][l+d])
            # This is a bit large. Let's do:
            # x[u][l] AND x[v][l+d] => e[i][d]
            for l in range(46 - d):
                solver.add_clause([-var_x(u, l), -var_x(v, l+d), var_e(i, d)])
                solver.add_clause([-var_x(v, l), -var_x(u, l+d), var_e(i, d)])

            # Also, if e[i][d] is true, then u and v must have difference d
            # e[i][d] => OR_l (x[u][l] AND x[v][l+d]) OR (x[v][l] AND x[u][l+d])
            # To encode this in CNF:
            # If e[i][d] is true and x[u][l] is true, then x[v][l+d] or x[v][l-d] must be true
            for l in range(46):
                clause = [-var_e(i, d), -var_x(u, l)]
                if l + d < 46:
                    clause.append(var_x(v, l + d))
                if l - d >= 0:
                    clause.append(var_x(v, l - d))
                solver.add_clause(clause)

    # Symmetry breaking
    # V[0] < V[1] < V[2]
    for l1 in range(46):
        for l2 in range(l1 + 1):
            solver.add_clause([-var_x(0, l1), -var_x(1, l2)])
            solver.add_clause([-var_x(1, l1), -var_x(2, l2)])

    # V[0] < V[21]
    for l1 in range(46):
        for l2 in range(l1 + 1):
            solver.add_clause([-var_x(0, l1), -var_x(21, l2)])

    print("Solving...")
    if solver.solve():
        print("SAT")
        model = solver.get_model()
        labels = [-1] * 24
        for v in range(24):
            for l in range(46):
                if model[var_x(v, l) - 1] > 0:
                    labels[v] = l
        print(labels)
    else:
        print("UNSAT")

solve()

